-- create role app_user
DO $rls$ BEGIN IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'app_user') THEN BEGIN CREATE ROLE "app_user" NOLOGIN; EXCEPTION WHEN duplicate_object OR unique_violation THEN NULL; END; END IF; IF EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'app_user' AND (rolsuper OR rolbypassrls)) THEN RAISE EXCEPTION USING MESSAGE = 'the role "app_user" exists with SUPERUSER or BYPASSRLS, so it bypasses every policy' || chr(10) || 'help: use another role name, or ALTER ROLE "app_user" NOSUPERUSER NOBYPASSRLS as a superuser'; END IF; IF EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'app_user' AND rolcanlogin <> false) THEN ALTER ROLE "app_user" NOLOGIN; END IF; IF EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'app_user' AND rolinherit <> true) THEN ALTER ROLE "app_user" INHERIT; END IF; IF EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'app_user' AND rolcreatedb <> false) THEN ALTER ROLE "app_user" NOCREATEDB; END IF; IF EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'app_user' AND rolcreaterole <> false) THEN ALTER ROLE "app_user" NOCREATEROLE; END IF; EXCEPTION WHEN insufficient_privilege THEN RAISE EXCEPTION USING MESSAGE = 'the migration role cannot set the attributes of the role "app_user": ' || SQLERRM || chr(10) || 'help: the migration role needs CREATEROLE, ADMIN OPTION on a role it did not create, and CREATEDB to change CREATEDB (docs/rls.md §3); or run the ALTER ROLE as a superuser'; END $rls$;
GRANT "app_user" TO "app_login";
-- create table posts
ALTER TABLE "posts" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "posts" FORCE ROW LEVEL SECURITY;
-- create grant on posts to app_user
GRANT SELECT ON "posts" TO "app_user";
-- create policy posts_app_user_insert on posts
CREATE POLICY "posts_app_user_insert" ON "posts" AS PERMISSIVE FOR INSERT TO "app_user" WITH CHECK (CAST(NULLIF(current_setting('brocanth.tenant_id', TRUE), '') AS bigint) IS NOT NULL AND "tenant_id" = CAST(NULLIF(current_setting('brocanth.tenant_id', TRUE), '') AS bigint) AND (CAST(NULLIF(current_setting('brocanth.user_id', TRUE), '') AS bigint) IS NOT NULL AND "author_id" = CAST(NULLIF(current_setting('brocanth.user_id', TRUE), '') AS bigint)));
-- create policy posts_app_user_select on posts
CREATE POLICY "posts_app_user_select" ON "posts" AS PERMISSIVE FOR SELECT TO "app_user" USING ((CAST(NULLIF(current_setting('brocanth.banned', TRUE), '') AS boolean) IS NOT NULL AND CAST(NULLIF(current_setting('brocanth.admin', TRUE), '') AS boolean) IS NOT NULL AND (((NOT CAST(NULLIF(current_setting('brocanth.banned', TRUE), '') AS boolean)) AND CAST(NULLIF(current_setting('brocanth.admin', TRUE), '') AS boolean)) OR ((NOT CAST(NULLIF(current_setting('brocanth.banned', TRUE), '') AS boolean)) AND (NOT CAST(NULLIF(current_setting('brocanth.admin', TRUE), '') AS boolean)) AND (CAST(NULLIF(current_setting('brocanth.tenant_id', TRUE), '') AS bigint) IS NOT NULL AND "tenant_id" = CAST(NULLIF(current_setting('brocanth.tenant_id', TRUE), '') AS bigint) AND ("status" = 'published' OR (CAST(NULLIF(current_setting('brocanth.user_id', TRUE), '') AS bigint) IS NOT NULL AND "author_id" = CAST(NULLIF(current_setting('brocanth.user_id', TRUE), '') AS bigint))))))) OR (CAST(NULLIF(current_setting('brocanth.user_id', TRUE), '') AS bigint) IS NOT NULL AND "author_id" = CAST(NULLIF(current_setting('brocanth.user_id', TRUE), '') AS bigint)));
-- create policy posts_app_user_update on posts
CREATE POLICY "posts_app_user_update" ON "posts" AS PERMISSIVE FOR UPDATE TO "app_user" USING (CAST(NULLIF(current_setting('brocanth.admin', TRUE), '') AS boolean) IS NOT NULL AND (CAST(NULLIF(current_setting('brocanth.admin', TRUE), '') AS boolean) OR ((NOT CAST(NULLIF(current_setting('brocanth.admin', TRUE), '') AS boolean)) AND (CAST(NULLIF(current_setting('brocanth.user_id', TRUE), '') AS bigint) IS NOT NULL AND "author_id" = CAST(NULLIF(current_setting('brocanth.user_id', TRUE), '') AS bigint) AND "status" = 'draft')))) WITH CHECK (CAST(NULLIF(current_setting('brocanth.admin', TRUE), '') AS boolean) IS NOT NULL AND (CAST(NULLIF(current_setting('brocanth.admin', TRUE), '') AS boolean) OR ((NOT CAST(NULLIF(current_setting('brocanth.admin', TRUE), '') AS boolean)) AND (CAST(NULLIF(current_setting('brocanth.user_id', TRUE), '') AS bigint) IS NOT NULL AND "author_id" = CAST(NULLIF(current_setting('brocanth.user_id', TRUE), '') AS bigint)))));
-- create usage on sequence posts_id_seq of posts to app_user
GRANT USAGE ON SEQUENCE "posts_id_seq" TO "app_user";
-- create grant INSERT on columns of posts to app_user
GRANT INSERT ("author_id", "tenant_id", "title") ON "posts" TO "app_user";
-- create grant UPDATE on columns of posts to app_user
GRANT UPDATE ("status", "title") ON "posts" TO "app_user";
